        print(e, "| from:", nodes.get(e['from_id'],{}).get('class_name'), "| to:", nodes.get(e['to_id'],{}).get('class_name'))
rooms = [n for n in st.get('nodes',[]) if n.get('category')=='Rooms']
print("ROOMS", [(n['id'], n['class_name']) for n in rooms])
# character edges
for e in edges:
    if e['from_id']==240 or e['to_id']==240:
        print("CHAR", e, nodes.get(e['from_id'],{}).get('class_name'), nodes.get(e['to_id'],{}).get('class_name'))

